window.deepArticles = window.deepArticles || {};

const princelyIndiaSources = [
  {href:"../settingBible%20-%20AltWWII.md",label:"Setting Bible — India and the post-Raj order"},
  {href:"../settingTimeline%20-%20AltWWII.md",label:"Setting Timeline — Indian successor-state development"},
  {href:"../transcript.md",label:"Master Transcript — princely sovereignty, regional systems, and arms economy"},
  {href:"../coProsperitySphereReference%20-%20AltWWII.md",label:"Greater East Asia reference — Hyderabad and the central Indian balance"}
];

const princelySystemDiagram = {src:"assets/diagrams/princely-india-system.svg",alt:"Diagram of the three practical levels and regional systems of princely India",caption:"Archive reconstruction · dispersed sovereignty without a collective state"};
const hyderabadCorridorDiagram = {src:"assets/diagrams/hyderabad-machilipatnam-corridor.svg",alt:"Schematic of Hyderabad's strategic corridor through Warangal and Vijayawada to Machilipatnam",caption:"Schematic reconstruction · political relationships, not a surveyed frontier"};
const princelyArmsDiagram = {src:"assets/diagrams/princely-arms-market.svg",alt:"Diagram showing the small-batch princely arms market from foreign design and finance through brokers to individual courts",caption:"Archive reconstruction · the full commercial package"};

const princelyArticle = config => ({
  category:"Indian successor states",
  eyebrow:"Princely India · post-1947",
  infoboxKicker:"Dispersed sovereignty after the Raj",
  ...config,
  sources:[...princelyIndiaSources,...(config.primarySources || [])],
  categories:config.categories || ["Princely states of India","Indian successor states","Breaking of the Raj"]
});

Object.assign(window.deepArticles,{
  "princely-states-india":princelyArticle({
    title:"Princely states of India",eyebrow:"Political ecology · 1947 onward",infoboxKicker:"Sovereign courts and protected principalities",flag:princelySystemDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6a writer=g kind=revision created=2026-08-16T03:30:00-06:00 -->Princely India is the dispersed system of independent rulers and small states that emerges from the Raj's collapse. It is not a federation, union, single bloc, or compact geographical region; many courts cooperate against larger claimants while insisting upon their separate sovereignty.<sup class='canon-note' data-provenance='a'>[a]</sup> Classification into sovereign states, associated principalities, protected chiefships, restored dynasties, and autonomous estates is compatible institutional synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6b writer=g kind=revision created=2026-08-16T03:30:00-06:00 -->The dispersed and non-federal character, regional breakup of the former agencies, Hyderabad's influence without general suzerainty, support for the weakest major northern claimant, anti-communist cooperation, and large small-batch arms market are established.<sup class='canon-note' data-provenance='a'>[a]</sup> A three-level taxonomy, formal regional systems, revived Chamber of Princes, and mature common conventions are compatible synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup> The recognized-state count, dynastic register, borders, classifications, shared institutions, and constitutional status of minor courts remain open.<!-- altwwii-writer-block:end -->",
    sections:[
      {id:"collapse",title:"End of paramountcy",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6c writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p>The Raj's withdrawal allows numerous princely states, former agency territories, and some previously annexed kingdoms to assert independent authority.<sup class='canon-note' data-provenance='a'>[a]</sup> Decisions by every ruler, regent, minister, commander, and local movement, and the legal effect of former agency headquarters, are incorporated reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"rush",title:"Early consolidation",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6d writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p>Post-Raj authority briefly resembles a pre-Company mosaic before rapid consolidation over weeks or months.<sup class='canon-note' data-provenance='a'>[a]</sup> Particular declarations, protectorates, revivals, enclave wars, disappearances, and survival factors are incorporated explanatory detail.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"levels",title:"Working classifications",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6e writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Working level</th><th>Compatible powers</th></tr></thead><tbody><tr><td>Sovereign princely state</td><td>Government, courts, army, subjecthood, banking, treaties, and sometimes currency.</td></tr><tr><td>Associated principality</td><td>Domestic authority under another court's strategic protection, representation, air defense, or port access.</td></tr><tr><td>Estate or chiefship</td><td>Hereditary land, tax, court, police, and customary authority inside a larger defense system.</td></tr></tbody></table></div><p>The three-level taxonomy and its jurisdictional boundaries are incorporated synthesis rather than a canonical constitutional scheme.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"regions",title:"Regional distribution",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6f writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p>The author establishes distinct princely mosaics in Central India, Gujarat and Kathiawar, Orissa and Chhattisgarh, Rajputana, the Deccan, Punjab, and the British-aligned south, rather than one contiguous princely state.<sup class='canon-note' data-provenance='a'>[a]</sup> Treating each as a formal regional system is incorporated organization.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"hyderabad",title:"Hyderabad",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6g writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p><a href='hyderabad.html'>Hyderabad</a> is the largest princely state, exercises major influence in central and western princely India, and sends forces against communist expansion while other courts preserve their independence.<sup class='canon-note' data-provenance='a'>[a]</sup> A standard package of loans, arms, advisers, repair, representation, and expeditionary aid is incorporated institutional detail.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"balance",title:"Balance of power",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6h writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p>The princes generally support whichever of Azad Hind, Congress India, and Hindustan is weakest because victory by one threatens the remaining small states.<sup class='canon-note' data-provenance='a'>[a]</sup> A uniform doctrine and its detailed instruments remain incorporated strategic synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"institutions",title:"Working cooperation",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6j writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p>Princely states cooperate when communists or larger claimants threaten them.<sup class='canon-note' data-provenance='a'>[a]</sup> A revived <a href='chamber-of-princes-india.html'>Chamber of Princes</a> handling recognition, transit, extradition, disputes, procurement, railways, and emergency defense without tax or command powers is compatible institutional reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"mature",title:"Working mature system",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-p2c6k writer=g kind=revision created=2026-08-16T03:30:00-06:00 --><p>Permanent military-commercial courts after 1965, with investments in armies, roads, water, air defense, capitals, dynastic education, and advisers, are compatible development of the established long-lived mosaic.<sup class='canon-note' data-provenance='e'>[e]</sup> No common date or development path is directly fixed.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"chamber-of-princes-india.html",kicker:"Common forum",label:"Chamber of Princes"},{href:"princely-balance-of-power.html",kicker:"Shared strategy",label:"Princely Balance of Power"},{href:"princely-arms-market.html",kicker:"Political economy",label:"Princely Arms Market"},{href:"hyderabad.html",kicker:"Largest court",label:"Hyderabad"}],
    facts:[["Period","Post-Raj"],["Established political form","Dispersed independent courts and states"],["Collective state","None"],["Largest princely state","Hyderabad"],["Proposed common forum","Revived Chamber of Princes"],["Established strategic tendency","Support the weakest major northern claimant"],["Established regions","Central, western, eastern, Rajputana, Deccan, Punjab, and south"],["Recognized-state count and classifications","Open"]]
  }),

  "chamber-of-princes-india":princelyArticle({
    title:"Chamber of Princes",eyebrow:"Inter-princely forum · revived after 1947",infoboxKicker:"Narendra Mandal",flag:princelySystemDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7a writer=g kind=revision created=2026-08-16T03:31:00-06:00 -->A revived Chamber of Princes, or <em>Narendra Mandal</em>, is a compatible common forum for the sovereign courts of post-Raj India.<sup class='canon-note' data-provenance='e'>[e]</sup> It would coordinate recognition, transit, railways, extradition, dynastic disputes, arms standards, and emergency defense without creating a legislature, treasury, army, or federal sovereign. The author establishes cooperation among independent princely states, but does not name or constitute this chamber.<sup class='canon-note' data-provenance='a'>[a]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7b writer=g kind=revision created=2026-08-16T03:31:00-06:00 -->The historical Chamber of Princes and its Narendra Mandal name are inherited pre-divergence institutions.<sup class='canon-note' data-provenance='p'>[p]</sup> Post-Raj princely independence, cooperation against common threats, and Hyderabad's active influence are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Revival of the Chamber, its agenda, committees, membership, regional durbars, limits, and Hyderabad's execution of agreed policy are compatible institutional synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup> Its existence, reconstitution, seat, charter, membership, voting, officers, budget, and later name remain open.<!-- altwwii-writer-block:end -->",
    sections:[
      {id:"predecessor",title:"Historical predecessor",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7c writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>The historical Chamber represented rulers beneath British paramountcy.<sup class='canon-note' data-provenance='p'>[p]</sup> Transformation after 1947 into a congress without the Viceroy, Political Department, or superior sovereign is compatible institutional reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"membership",title:"Working membership",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7d writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>Representation for large states, associated principalities, regional concerts, and selected chiefships, with disputed recognition and external personality, is incorporated membership design.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"work",title:"Working agenda",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7e writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>Mediation of recognition, transit, extradition, succession, railways, customs, arms standards, and troop passage through committees that leave implementation to governments is compatible institutional design.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"defense",title:"Working defense consultation",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7f writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>Princely states cooperate against communist conquest and larger Indian claimants.<sup class='canon-note' data-provenance='a'>[a]</sup> Chamber deliberation over threats, aid, transit, displaced rulers, and non-binding common responses is incorporated procedure.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"hyderabad",title:"Working role of Hyderabad",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7g writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p><a href='hyderabad.html'>Hyderabad</a> is the most powerful princely state and sends forces against communist expansion.<sup class='canon-note' data-provenance='a'>[a]</sup> Execution of Chamber resolutions through aircraft, engineers, credit, ammunition, and expeditionary forces is incorporated coordination design.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"limits",title:"Working limits",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7h writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>No compulsory budget, common citizenship, federal court, permanent army, binding mediation, or uniform procurement is compatible with the established insistence on princely independence.<sup class='canon-note' data-provenance='e'>[e]</sup> These are proposed limits, not enacted constitutional clauses.</p><!-- altwwii-writer-block:end -->"},
      {id:"regional",title:"Working regional conferences",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7n writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>Smaller durbars or conferences in Rajputana, Central India, the western states, and eastern defense groupings, settling local issues and forwarding positions to the Chamber, are incorporated organizational reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"significance",title:"Working political function",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c3d7k writer=g kind=revision created=2026-08-16T03:31:00-06:00 --><p>A collective voice strong enough to resist absorption but too weak to dissolve member sovereignty is compatible explanation for a revived Chamber's durability.<sup class='canon-note' data-provenance='e'>[e]</sup> The institution's actual survival is not directly established.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"princely-states-india.html",kicker:"Political system",label:"Princely States of India"},{href:"princely-balance-of-power.html",kicker:"Common strategy",label:"Princely Balance of Power"},{href:"rajputana.html",kicker:"Regional concert",label:"Rajputana"},{href:"central-indian-princely-states.html",kicker:"Regional mosaic",label:"Central Indian Princely States"}],
    facts:[["Historical name","Chamber of Princes; Narendra Mandal"],["Post-Raj status","Compatible institutional reconstruction"],["Proposed character","Consultative inter-sovereign forum"],["Working members","Courts, concerts, and selected principalities"],["Working remit","Recognition, transit, railways, disputes, procurement, and defense"],["Proposed tax and command powers","None"],["Existence, reconstitution, seat, charter, membership, and officers","Open"]]
  }),

  "central-indian-princely-states":princelyArticle({
    title:"Central Indian princely states",eyebrow:"Regional mosaic · Gwalior, Indore, and Malwa",infoboxKicker:"Central Indian political system",flag:princelySystemDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8a writer=g kind=revision created=2026-08-16T10:05:00-06:00 -->The Central Indian princely states are the independent courts and small states left by the breakup of the Central India Agency and Gwalior Residency. They form a fragmented mosaic around Indore and are broadly associated with the larger state of Hyderabad.<sup class='canon-note' data-provenance='a'>[a]</sup> A detailed system of interlocking enclaves, protected territories, transit agreements, and differentiated regional centers is compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8b writer=g kind=revision created=2026-08-16T10:05:00-06:00 -->Breakup of the Central India Agency and Gwalior Residency, the survival of numerous independent states, their mosaic around Indore, Hyderabad's strong influence, princely cooperation against communist expansion, balance among the three major northern claimants, and a large market for small military orders are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Exact court roles, enclave and transit arrangements, aid packages, regional institutions, procurement histories, borders, leadership, and alignments of minor courts are compatible synthesis or remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"inheritance",title:"After the Central India Agency",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8c writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>The British Central India Agency and Gwalior Residency were administrative relationships rather than a single state.<sup class='canon-note' data-provenance='p'>[p]</sup> Their post-Raj breakup leaves most constituent princely states independent.<sup class='canon-note' data-provenance='a'>[a]</sup> The survival of particular military estates, railway enclaves, and rival claims is incorporated reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"centers",title:"Gwalior, Indore, and Bhopal",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8d writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>Gwalior, Indore, and Bhopal are inherited regional courts.<sup class='canon-note' data-provenance='p'>[p]</sup> The author specifically locates the central mosaic around Indore.<sup class='canon-note' data-provenance='a'>[a]</sup> Assigning Gwalior the leading military role, Indore the commercial center, Bhopal a distinctive diplomatic role, and all three a deliberate competitive balance is compatible regional synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"mosaic",title:"Bundelkhand and Malwa mosaic",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8e writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>The central princely states form part of the canonically fragmented Indian mosaic rather than one contiguous regional state.<sup class='canon-note' data-provenance='a'>[a]</sup> A patchwork of Bundelkhand courts, Malwa states, estates, enclaves, and roads crossing several jurisdictions is compatible geographic reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"transit",title:"Transit as foreign policy",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8f writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>Multiple permissions for troops, arms, mail, railway wagons, and couriers, together with the resulting influence of rail companies, brokers, and station commanders, are compatible consequences of the established fragmentation rather than directly fixed institutions.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"hyderabad",title:"Hyderabad's influence",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8g writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>Hyderabad is the largest princely state, exercises strong influence across central and western princely India, and sends forces through other princely territories against communist expansion without erasing their asserted independence.<sup class='canon-note' data-provenance='a'>[a]</sup> Loans, technical advisers, overhaul, air defense, and a standard protective relationship are compatible institutional detail.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"arms",title:"A market for small-batch weapons",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8h writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>The large number of small independent rulers creates a substantial market for limited military orders.<sup class='canon-note' data-provenance='a'>[a]</sup> Purchases tailored to individual fortresses, roads, airfields, and frontiers, including assault guns, armored trains, radar, and short-run aircraft, are compatible procurement detail.<sup class='canon-note' data-provenance='e'>[e]</sup> The author allows one princely state to own the sole <a href='object-279-india.html'>Object 279-derived prototype</a>, but does not place that patron in Central India.<sup class='canon-note' data-provenance='a'>[a]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"balance",title:"Balancing the claimants",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8j writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>Princely states generally support whichever of Congress India, Hindustan, and Azad Hind is weakest because the elimination of one would leave the victor free to threaten them.<sup class='canon-note' data-provenance='a'>[a]</sup> The exact mix of transit, intelligence, credit, and matériel supplied by Central Indian courts remains open.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"identity",title:"Local sovereignty",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-c4e8k writer=g kind=revision created=2026-08-16T10:05:00-06:00 --><p>The central courts insist upon their separate independence and do not claim to be one federation or an all-India government.<sup class='canon-note' data-provenance='a'>[a]</sup> The political language by which individual soldiers, officials, and dynasties express that sovereignty remains open.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"princely-states-india.html",kicker:"Wider system",label:"Princely States of India"},{href:"chamber-of-princes-india.html",kicker:"Common forum",label:"Chamber of Princes"},{href:"princely-arms-market.html",kicker:"Regional economy",label:"Princely Arms Market"},{href:"hyderabad.html",kicker:"Security patron",label:"Hyderabad"}],
    facts:[["Established political form","Independent princely mosaic"],["Established geographic center","Around Indore"],["Inherited major courts","Gwalior, Indore, and Bhopal"],["Established regional association","Strong Hyderabad influence"],["Established common threat","Communist expansion"],["Established strategic tendency","Support the weakest major northern claimant"],["Established procurement context","Large market of small state orders"],["Borders, institutions, court roles, and complete state list","Open"]]
  }),

  "western-indian-princely-states":princelyArticle({
    title:"Western Indian princely states",eyebrow:"Commercial mosaic · Gujarat and Kathiawar",infoboxKicker:"Western Indian court and port system",flag:princelySystemDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1a writer=g kind=revision created=2026-08-16T10:15:00-06:00 -->The western Indian princely states are the numerous small independent states left by the breakup of the Gujarat States Agency and the Kathiawar political system. The region is centered around Ahmedabad, while Rajkot and Gondal remain emphatically separate sovereigns and Hyderabad exercises substantial western influence.<sup class='canon-note' data-provenance='a'>[a]</sup> A shared commercial system of ports, banking, transit, and defense agreements is compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1b writer=g kind=revision created=2026-08-16T10:15:00-06:00 -->Breakup of the Gujarat States Agency, survival of numerous western and Kathiawar states around Ahmedabad, the separate sovereignty of Rajkot and Gondal, Hyderabad's western influence, and participation in the wider small-state arms market are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Survival of every historical court, Ahmedabad's exact government and economic primacy, port and textile systems, merchant institutions, transit and defense agreements, borders, membership, and later hierarchy remain compatible synthesis or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"agency",title:"Gujarat and Kathiawar after agency rule",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1c writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>The historical Gujarat and Kathiawar agencies grouped numerous states and estates for British political administration rather than forming a single sovereign state.<sup class='canon-note' data-provenance='p'>[p]</sup> Their breakup contributes most of the western princely mosaic.<sup class='canon-note' data-provenance='a'>[a]</sup> The disposition of agency headquarters and inherited administrative machinery remains open.</p><!-- altwwii-writer-block:end -->"},
      {id:"courts",title:"Separate neighboring courts",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1d writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>Rajkot and Gondal remain separate and insist upon their independent sovereignty.<sup class='canon-note' data-provenance='a'>[a]</sup> Bhavnagar, Nawanagar, and Junagadh are inherited neighboring courts,<sup class='canon-note' data-provenance='p'>[p]</sup> but their exact post-Raj survival, alignments, and common arrangements are not directly fixed.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"ahmedabad",title:"Ahmedabad without a western empire",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1e writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>The author places the western Indian states around Ahmedabad without making the city sovereign over the surrounding princely courts.<sup class='canon-note' data-provenance='a'>[a]</sup> Its status as the largest industrial, textile, banking, republican, standards-setting, or diplomatic center is compatible regional synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"ports",title:"Ports, customs, and merchant houses",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1f writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>Connections through western ports to Sindh, Bombay, the Gulf, East Africa, and a bullion-clearing economy, together with customs concessions, warehousing, shipping insurance, and merchant credit, are compatible commercial reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"transit",title:"The western transit web",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1g writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>British control of Bombay itself alongside princely territory in the wider province is established.<sup class='canon-note' data-provenance='a'>[a]</sup> A trade-and-arms web linking <a href='sindh.html'>Sindh</a>, the <a href='bombay-joint-port.html'>Bombay joint port</a>, <a href='rajputana.html'>Rajputana</a>, and Central India through ruler-controlled roads, piers, and railway segments is compatible logistical synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"defense",title:"Defense through overlapping agreements",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1h writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>The western states are separate polities rather than one uniform regional army, and Hyderabad exercises significant influence among them.<sup class='canon-note' data-provenance='a'>[a]</sup> Guards, field units, contracted air defense and armor, regional agreements, Chamber appeals, command rules, and cost sharing are compatible defense reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"arms",title:"A merchant arms market",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1j writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>The fragmented princely order creates a large market because many small rulers seek their own military equipment.<sup class='canon-note' data-provenance='a'>[a]</sup> A western network of bankers, brokers, ports, and repair shops moving incompatible equipment, ammunition, mechanics, and credit is compatible elaboration of that market.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"sovereignty",title:"Commercial modernity and dynastic survival",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-w6g1k writer=g kind=revision created=2026-08-16T10:15:00-06:00 --><p>The western courts preserve separate dynastic and local claims within a modern postwar setting.<sup class='canon-note' data-provenance='a'>[a]</sup> Their use of company law, radio, motor transport, insurance, and foreign advisers is compatible social and institutional reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"princely-states-india.html",kicker:"Wider system",label:"Princely States of India"},{href:"princely-arms-market.html",kicker:"Commercial institution",label:"Princely Arms Market"},{href:"central-indian-princely-states.html",kicker:"Eastern neighbor",label:"Central Indian Princely States"},{href:"bombay-joint-port.html",kicker:"Maritime hinge",label:"Bombay Joint Port"}],
    facts:[["Established region","Gujarat and Kathiawar"],["Established geographic center","Around Ahmedabad"],["Established separate sovereigns","Rajkot and Gondal"],["Inherited neighboring courts","Bhavnagar, Nawanagar, and Junagadh"],["Established political form","Numerous independent states"],["Established outside influence","Hyderabad"],["Established procurement context","Large market of small state orders"],["Borders, governments, economy, institutions, and complete register","Open"]]
  }),

  "eastern-indian-princely-states":princelyArticle({
    title:"Eastern Indian princely states",eyebrow:"Revolutionary frontier · Orissa and Chhattisgarh",infoboxKicker:"Eastern princely and forest conflict system",flag:princelySystemDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2a writer=g kind=revision created=2026-08-16T10:16:00-06:00 -->The eastern princely states survive in the post-Raj Orissa region and through the breakup of the Chhattisgarh States Agency. The author names Bamra, Hindol, and a state dictated as “Afgara,” and establishes overlapping princely, TPS, Azad Hind, and Hyderabadi activity across Orissa, the central provinces, and Bastar.<sup class='canon-note' data-provenance='a'>[a]</sup> Inherited geography supports Athgarh as the identification of “Afgara.”<sup class='canon-note' data-provenance='p'>[p]</sup> A complete roster of surviving courts, protected towns, chiefships, tribal authorities, and contested countryside is compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2b writer=g kind=revision created=2026-08-16T10:16:00-06:00 -->Eastern princely survival in the Orissa region; breakup of the Chhattisgarh States Agency; the author-named “Afgara,” Bamra, and Hindol; strong TPS control and parallel governance; Azad Hind–communist contact around Sambalpur and the Mahanadi; occasional communist destruction of courts; princely and Hyderabadi counteraction; and the late-1980s Japanese-assisted rollback and corporate administration of some recovered states are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Identification of “Afgara” as Athgarh follows inherited geography.<sup class='canon-note' data-provenance='p'>[p]</sup> Exact rulers, borders, survivor list, protectorates, campaign institutions, and ownership of contested countryside remain open or synthesized.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"region",title:"The former Orissa and Chhattisgarh agencies",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2c writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>The historical Orissa and Chhattisgarh agencies administered many distinct princely states rather than single nations.<sup class='canon-note' data-provenance='p'>[p]</sup> The author establishes eastern princely states in the Orissa region, names “Afgara,” Bamra, and Hindol, and separately establishes the breakup of the Chhattisgarh States Agency.<sup class='canon-note' data-provenance='a'>[a]</sup> Historical geography identifies “Afgara” as Athgarh and also places Mayurbhanj, Dhenkanal, Keonjhar, Talcher, Patna, Sonepur, Bastar, Kanker, and Raigarh in this wider agency world,<sup class='canon-note' data-provenance='p'>[p]</sup> but their individual post-Raj outcomes remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"spectrum",title:"A spectrum of survival",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2d writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>A few princely states are destroyed by communist forces, while neighboring courts usually combine against the new threat and Hyderabad is willing to intervene across their borders.<sup class='canon-note' data-provenance='a'>[a]</sup> Particular rulers retaining fortified towns, accepting protection, or holding only palaces, roads, and garrisons are compatible local reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"sambalpur",title:"The Sambalpur–Mahanadi contact zone",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2e writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>Azad Hind and communist forces usually meet around Sambalpur on the Mahanadi, where Calcutta's southwestern advance encounters communist power.<sup class='canon-note' data-provenance='a'>[a]</sup> A seasonally changing patchwork of princely, village, tribal, and garrison authority is compatible frontier reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"tps",title:"TPS political depth",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2f writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p><a href='telangana-praja-samakhya.html'>TPS</a> exercises substantial control and parallel government across the central and eastern princely region, including much of the central provinces and Bastar.<sup class='canon-note' data-provenance='a'>[a]</sup> Its exact combination of armed columns, village committees, forest networks, land redistribution, clandestine cells, and agitation inside princely forces is compatible operational synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"ratchet",title:"Communist conquest and princely response",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2g writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>Communist conquest of a princely state is relatively rare because it gives neighboring rulers a clear common target. Princely cooperation, sometimes reinforced by Hyderabad, then checks further expansion.<sup class='canon-note' data-provenance='a'>[a]</sup> A uniform five-stage revolutionary cycle and its precise territorial effects are not directly fixed.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"hyderabad",title:"Hyderabadi expeditionary defense",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2h writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>Hyderabad is willing to send forces across territory it does not own in order to destroy communist forces and preserve neighboring princely states.<sup class='canon-note' data-provenance='a'>[a]</sup> The effect of each intervention upon arms dependence, strategic access, and Hyderabad's political influence remains compatible interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"azad",title:"Azad Hind's limited priority",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2j writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>Azad Hind takes selected positions in the eastern princely region but remains principally concerned with Congress India; its ordinary southwestern contact with communist forces lies around Sambalpur.<sup class='canon-note' data-provenance='a'>[a]</sup> Particular protection commitments to palaces, forest roads, and disputed districts remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"later",title:"Japanese-assisted rollback in the late 1980s",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-e7h2k writer=g kind=revision created=2026-08-16T10:16:00-06:00 --><p>By 1990, Japanese volunteers, expeditionary forces, and zaibatsu security forces working with princely states have severely reduced but not eliminated TPS control. Some states recovered from TPS are placed under charter-company authority instead of being returned to a prince or heir.<sup class='canon-note' data-provenance='a'>[a]</sup> The formal titles <a href='anti-tps-campaign.html'>anti-TPS campaign</a> and <a href='chartered-restoration-territories.html'>chartered restoration territories</a>, together with a uniform 1986–90 chronology and administrative model, are compatible institutional synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"telangana-praja-samakhya.html",kicker:"Revolutionary rival",label:"Telangana Praja Samakhya"},{href:"anti-tps-campaign.html",kicker:"Late campaign",label:"Anti-TPS Campaign"},{href:"princely-states-india.html",kicker:"Wider system",label:"Princely States of India"},{href:"hyderabad.html",kicker:"Security patron",label:"Hyderabad"}],
    facts:[["Established regions","Orissa and Chhattisgarh"],["Author-named eastern states","“Afgara,” Bamra, and Hindol"],["Inherited identification","Athgarh for “Afgara”"],["Established conflict hinge","Sambalpur–Mahanadi approaches"],["Principal revolutionary power","TPS"],["Established princely patron","Hyderabad"],["Late-1980s intervention","Japanese, zaibatsu, and princely forces"],["Rulers, borders, survivor list, protectorates, and campaign institutions","Open"]]
  }),

  "hyderabad-machilipatnam-corridor":princelyArticle({
    title:"Hyderabad–Machilipatnam corridor",eyebrow:"Strategic trade route · Deccan to Bay of Bengal",infoboxKicker:"Hyderabad's maritime outlet",flag:hyderabadCorridorDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9a writer=g kind=revision created=2026-08-16T10:06:00-06:00 -->Hyderabad controls a strategic strip from its capital to the strongly associated princely state of Vijayawada and onward to Machilipatnam. The route is Hyderabad's principal maritime outlet; Warangal is separately established as an important nearby state.<sup class='canon-note' data-provenance='a'>[a]</sup> Placing Warangal directly on the corridor and defining its road, railway, treaty, customs, and security machinery are compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9b writer=g kind=revision created=2026-08-16T10:06:00-06:00 -->The Hyderabad–Vijayawada–Machilipatnam strip, the corridor's maritime and export role, Vijayawada's strong association, Warangal's nearby importance, German financial and material support before the mid-1980s, and Hyderabad's subsequent turn toward Japan are established.<sup class='canon-note' data-provenance='a'>[a]</sup> A route through Warangal, exact borders, treaty names, railway ownership, customs division, garrisons, cargo systems, defenses, Japanese investment program, and constitutional relationships along the route remain open or are compatible synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"necessity",title:"Hyderabad's maritime outlet",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9c writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>The corridor is Hyderabad's principal route for bringing in and sending out export goods by sea.<sup class='canon-note' data-provenance='a'>[a]</sup> Dependence upon particular foreign machinery, fuel, advisers, weapons, and rival railways is compatible logistical detail.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"route",title:"The eastward route",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9d writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>The strategic strip runs from Hyderabad to Vijayawada and reaches the coast at Machilipatnam.<sup class='canon-note' data-provenance='a'>[a]</sup> Routing it through Warangal and describing it as a chain of rail, road, warehousing, customs, telegraph, security, and political agreements are compatible reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"warangal",title:"Warangal and the inner corridor",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9e writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>Warangal is established as an important state near Hyderabad.<sup class='canon-note' data-provenance='a'>[a]</sup> Its position on the corridor, role as a transport hinge, garrison and workshop center, and exposure to <a href='telangana-praja-samakhya.html'>TPS</a> are compatible operational synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"vijayawada",title:"Vijayawada's associated sovereignty",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9f writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>Vijayawada is a princely state strongly associated with Hyderabad and is central to the corridor's importance.<sup class='canon-note' data-provenance='a'>[a]</sup> Dependence upon the Nizam for defense, a princely or coalition government, and reserved local rights over military passage, revenue, and succession are compatible constitutional possibilities.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"port",title:"Machilipatnam and maritime access",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9g writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>Machilipatnam is the coastal terminus through which Hyderabad conducts its principal export traffic.<sup class='canon-note' data-provenance='a'>[a]</sup> Specific cargoes, port security, dredging, and procedures following closure of the port are compatible logistical reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"defense",title:"Defending a narrow strategic asset",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9h writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>Vulnerability to TPS, neighboring courts, sabotage, bridge failure, and political defection, together with garrisons, railway troops, air reconnaissance, repair units, and route-preservation treaties, is compatible operational synthesis rather than directly established corridor history.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"industry",title:"The corridor and the arms economy",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9j writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>Hyderabad and other princely states are established commercial centers for prototype work, repair, and re-export.<sup class='canon-note' data-provenance='a'>[a]</sup> Connecting the <a href='hyderabadi-arms-industry.html'>Hyderabadi arms industry</a> to corridor traffic in imported machine tools, engines, alloys, specialists, and exported short-run weapons is compatible industrial synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"japan",title:"Turn toward Japan in the mid-1980s",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-h5f9k writer=g kind=revision created=2026-08-16T10:06:00-06:00 --><p>Germany initially provides Hyderabad chiefly with money and material supplies, then reduces its support during the German–Japanese détente of 1985 or 1986. Unable to turn to Britain, Hyderabad subsequently turns toward Japan, which regards the shift as a success in its Indian campaign.<sup class='canon-note' data-provenance='a'>[a]</sup> A formal association, defined investment and communications programs, security assistance, and use of the corridor as Japan's western gateway to princely India remain compatible diplomatic synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"hyderabad.html",kicker:"Principal state",label:"Hyderabad"},{href:"hyderabadi-arms-industry.html",kicker:"Industrial user",label:"Hyderabadi Arms Industry"},{href:"anti-tps-campaign.html",kicker:"Security campaign",label:"Anti-TPS Campaign"},{href:"princely-arms-market.html",kicker:"Trade system",label:"Princely Arms Market"}],
    facts:[["Established route","Hyderabad–Vijayawada–Machilipatnam"],["Established function","Principal maritime and export outlet"],["Coastal terminus","Machilipatnam"],["Established nearby state","Warangal"],["Established associated state","Vijayawada"],["Earlier external support","German money and supplies"],["Mid-1980s diplomatic turn","Toward Japan"],["Warangal routing, borders, treaties, infrastructure, defenses, and formal status","Open"]]
  }),

  "princely-balance-of-power":princelyArticle({
    title:"Princely balance of power",eyebrow:"Indian grand strategy · 1950s onward",infoboxKicker:"Survival doctrine of the courts",flag:princelySystemDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3a writer=g kind=revision created=2026-08-16T10:25:00-06:00 -->Princely rulers generally support whichever of Azad Hind, Congress India, and Hindustan is weakest because the defeat of the other two would leave the victor free to threaten the smaller states.<sup class='canon-note' data-provenance='a'>[a]</sup> Treating this recurring tendency as a shared doctrine with standard rules and instruments is compatible strategic synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3b writer=g kind=revision created=2026-08-16T10:25:00-06:00 -->General support for the weakest of the three major northern claimants, fear of conquest after one claimant defeats the others, direct cooperation against communist expansion, and continued princely division are established.<sup class='canon-note' data-provenance='a'>[a]</sup> A formal balancing doctrine, development chronology, universal participation, covert agreements, subsidy totals, intelligence networks, common institutions, and the behavior of every court remain compatible synthesis or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"logic",title:"Survival rather than solidarity",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3c writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>The princes are radically autonomous and do not operate as one unanimous group, but many recognize that the victory of one major northern claimant would endanger them next.<sup class='canon-note' data-provenance='a'>[a]</sup> A minimal consensus functioning as an insurance system is compatible interpretation rather than a common constitutional program.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"big-three",title:"The three northern claimants",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3d writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>The author identifies <a href='azad-hind.html'>Azad Hind</a>, <a href='congress-india.html'>Congress India</a>, and <a href='hindustan.html'>Hindustan</a> as the three powers whose victory over the others would expose the princely states.<sup class='canon-note' data-provenance='a'>[a]</sup> A uniform conception of them as a formally defined “Big Three” is compatible analytical shorthand.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"support",title:"Possible instruments of balance",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3e writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>Transit, credit, matériel, intelligence, railway priority, airfield access, volunteers, diplomatic recognition, and foreign advisers are compatible means by which separate courts might assist a weaker claimant.<sup class='canon-note' data-provenance='e'>[e]</sup> The transcript does not define a standard package, decision process, or preference for deniable aid.</p><!-- altwwii-writer-block:end -->"},
      {id:"examples",title:"Changing direction",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3f writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>Because support follows relative weakness rather than permanent loyalty, a beneficiary can later become the object of balancing.<sup class='canon-note' data-provenance='a'>[a]</sup> Specific hypothetical alignments among Azad Hind, Congress India, Hindustan, Rajputana, and the Pakistani successor states illustrate the logic but do not establish particular agreements.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"communists",title:"The different TPS problem",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3g writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>Few princely states are willing to work with the communist alternative. When communist forces destroy one court, neighboring princes gain a clear common target, cooperate directly, and may receive Hyderabadi intervention.<sup class='canon-note' data-provenance='a'>[a]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"institutions",title:"Possible institutional expression",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3h writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>A revived <a href='chamber-of-princes-india.html'>Chamber of Princes</a>, regional durbars, transit conventions, credit networks, arms standards, and Hyderabad-backed execution of common policy are compatible institutional reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup> The author establishes cooperation, not these bodies or procedures.</p><!-- altwwii-writer-block:end -->"},
      {id:"limits",title:"Limits of balancing",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3j writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>The established tendency does not make the princely states unanimous or prevent individual courts from collapsing.<sup class='canon-note' data-provenance='a'>[a]</sup> Misjudged threats, withheld transit, private wars, and balancing as the decisive cause of India's continued division are compatible strategic interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Durable fragmentation",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-b8j3k writer=g kind=revision created=2026-08-16T10:25:00-06:00 --><p>The princely states remain numerous, independent, and strategically relevant rather than merging into one bloc.<sup class='canon-note' data-provenance='a'>[a]</sup> Explaining their durability through the combined effect of credit, roads, armies, diplomatic access, and local legitimacy is compatible synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"princely-states-india.html",kicker:"Participating system",label:"Princely States of India"},{href:"chamber-of-princes-india.html",kicker:"Coordinating forum",label:"Chamber of Princes"},{href:"india-successors.html",kicker:"Regional order",label:"Indian Successor States"},{href:"rajputana.html",kicker:"Western concert",label:"Rajputana"}],
    facts:[["Established behavior","General support for the weakest major northern claimant"],["Claimants balanced","Azad Hind, Congress India, and Hindustan"],["Established rationale","A sole victor would threaten the princely states next"],["Established communist response","Direct cooperation and Hyderabadi intervention"],["Established political character","Autonomous courts without unanimity"],["Proposed instruments","Transit, credit, intelligence, matériel, and diplomacy"],["Proposed institutions","Chamber of Princes and regional durbars"],["Formal doctrine, chronology, and universal participation","Open"]]
  }),

  "princely-arms-market":princelyArticle({
    title:"Princely arms market",eyebrow:"Small-batch military commerce · 1950s onward",infoboxKicker:"Fragmented procurement economy",flag:princelyArmsDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4a writer=g kind=revision created=2026-08-16T10:26:00-06:00 -->The fragmentation of princely India creates a large military market because numerous small independent rulers seek equipment and munitions for their own forces.<sup class='canon-note' data-provenance='a'>[a]</sup> A full-service commercial system bundling weapons with credit, ammunition, training, transport, insurance, and repair is compatible market reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4b writer=g kind=revision created=2026-08-16T10:26:00-06:00 -->A large arms market created by many small princely customers, limited orders for individual rulers, multiple foreign streams of equipment, Russian-derived experimental possibilities, and an author-allowed single Object 279-derived princely prototype are established.<sup class='canon-note' data-provenance='a'>[a]</sup> “Small-batch procurement” as a unified system, incompatible inventories, full-service brokers, commodity credit, exact supplier mix, Hyderabad's showroom role, firms, prices, contracts, routes, and the equipment of individual courts are compatible synthesis or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"different",title:"A market of small rulers",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4c writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>Numerous independent rulers seek their own limited quantities of military hardware rather than buying through one Indian procurement authority.<sup class='canon-note' data-provenance='a'>[a]</sup> Illustrative orders combining fixed numbers of tanks, aircraft, radar sets, machine guns, ammunition, and engineers are compatible examples.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"package",title:"The full commercial package",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4d writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>Dealers arranging credit, commodity repayment, insurance, diplomatic introductions, transit fees, bribery, shipping, mechanics, training, ammunition, spares, and warehousing are compatible commercial reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup> The transcript establishes demand, not a standard service bundle.</p><!-- altwwii-writer-block:end -->"},
      {id:"suppliers",title:"Multiple equipment streams",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4e writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>German, Japanese, British, and Russian-derived equipment all reaches parts of princely India at different times.<sup class='canon-note' data-provenance='a'>[a]</sup> American supply, a five-system inventory, neutral brokers, bullion settlement, and persistent mixed fleets are compatible market synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"routes",title:"Brokers and sovereign borders",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4f writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>Merchant houses, railway companies, ports, arms agents, and court diplomats negotiating movement through the <a href='western-indian-princely-states.html'>western states</a>, Central India, Sindh, Bombay, and the <a href='hyderabad-machilipatnam-corridor.html'>Hyderabad corridor</a> are compatible logistical reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup> Exact routes and their relative value remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"hyderabad",title:"Hyderabad as workshop and showroom",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4g writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>Hyderabad is a major princely military-industrial power with imported technical lineages.<sup class='canon-note' data-provenance='a'>[a]</sup> Its combination of émigré design teams, repair plants, court finance, short-run client production, and prototype orders with later export potential is compatible industrial synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"experimental",title:"Experimental purchases",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4h writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>The author allows no more than perhaps one <a href='object-279-india.html'>Object 279-derived prototype</a> to be built for a princely owner.<sup class='canon-note' data-provenance='a'>[a]</sup> A general market in rejected national designs and purchases for particular fortresses or prestige functions is compatible explanation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"consequences",title:"Military consequences",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4j writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>Deterrent value, incompatible ammunition, radios, engines, and training, broker dependence, and difficulty maintaining readiness through political disruption are compatible consequences of fragmented procurement.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"politics",title:"Commerce as diplomacy",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-a9k4k writer=g kind=revision created=2026-08-16T10:26:00-06:00 --><p>Contracts linking courts, creditors, transit states, foreign suppliers, and technical communities, and thereby carrying recognition, access, influence, and intelligence alongside hardware, are compatible diplomatic interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"hyderabadi-arms-industry.html",kicker:"Principal workshop",label:"Hyderabadi Arms Industry"},{href:"object-279-india.html",kicker:"Famous prototype",label:"Object 279 Assault-Tank Project"},{href:"industrial-asylum.html",kicker:"Technical labor",label:"Industrial Asylum"},{href:"indian-bullion-economy.html",kicker:"Settlement system",label:"Indian Bullion Economy"}],
    facts:[["Established cause","Numerous small independent princely customers"],["Established order scale","Limited quantities for individual rulers"],["Established equipment streams","German, Japanese, British, and Russian-derived"],["Established major princely power","Hyderabad"],["Author-allowed exceptional purchase","Perhaps one Object 279-derived prototype"],["Proposed services","Credit, transport, training, ammunition, repair, and insurance"],["Routes, suppliers, settlement, firms, prices, and contracts","Open"],["Market size","Large; exact value open"]]
  }),

  "object-279-india":princelyArticle({
    title:"Object 279 assault-tank project",eyebrow:"Experimental armored vehicle · Central India",infoboxKicker:"One-off artillery-zone tank",flag:princelyArmsDiagram,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5a writer=g kind=revision created=2026-08-16T10:27:00-06:00 -->The author allows an Indian Object 279-derived design to reinterpret the Soviet vehicle as protection against extremely heavy artillery shells or barrages rather than nuclear shock, with no more than perhaps one prototype built for an unspecified princely state.<sup class='canon-note' data-provenance='a'>[a]</sup> A Hyderabadi Kirov émigré bureau, Central Indian commission, and Gwalior patron are compatible development choices, not established history.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5b writer=g kind=revision created=2026-08-16T10:27:00-06:00 -->The artillery-barrage reinterpretation and the possibility of no more than one princely prototype are direct authorial parameters.<sup class='canon-note' data-provenance='a'>[a]</sup> The historical Object 279's four-track, heavily armored form and Soviet design lineage are inherited.<sup class='canon-note' data-provenance='p'>[p]</sup> Actual construction, designation, date, specifications, patron, Hyderabadi Kirov lineage, Central Indian location, Gwalior candidacy, trials, service, and prestige role remain compatible synthesis or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"origin",title:"A Soviet design without its nuclear mission",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5c writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>The historical Object 279 was associated with a Soviet breakthrough and nuclear-battlefield requirement.<sup class='canon-note' data-provenance='p'>[p]</sup> The author allows its recognizable Indian descendant to be justified instead by survival amid extremely large artillery shells or barrages.<sup class='canon-note' data-provenance='a'>[a]</sup> A detailed fortified-zone environment of fragments, collapsing earth, waterlogged ground, mines, obstacles, and antitank fire is compatible engineering synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"survival",title:"Surviving the artillery storm",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5d writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>The inherited Object 279 form includes a curved armored hull and four-track running gear.<sup class='canon-note' data-provenance='p'>[p]</sup> Deflection of fragments, blast management, low ground pressure, mobility after partial damage, and the exclusion of direct heavy-artillery hits are compatible performance interpretations.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"mission",title:"Possible breakthrough mission",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5e writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>Operation inside a very heavy artillery barrage is the authorial rationale.<sup class='canon-note' data-provenance='a'>[a]</sup> Crossing a narrow devastated approach, destroying strongpoints, and serving one Central Indian fortress sector are compatible mission design rather than fixed requirements.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"bureau",title:"Possible Hyderabadi Kirov lineage",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5f writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>Deriving the project from Kotin–Kirov expertise in the <a href='hyderabadi-arms-industry.html'>Hyderabadi arms establishment</a>, and assigning that establishment the engineers, workshop, and court-contract culture needed to construct it, is compatible industrial synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"patron",title:"The possible princely commission",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5g writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>The author suggests that the possible prototype might be principally owned by one unspecified princely state.<sup class='canon-note' data-provenance='a'>[a]</sup> A Central Indian ruler, and Gwalior in particular, remain compatible patron candidates rather than canon.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"limits",title:"Why no more than one",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5h writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>The artillery rationale is insufficient for more than perhaps one prototype.<sup class='canon-note' data-provenance='a'>[a]</sup> Excessive width and weight, bridge and rail limits, mechanical complexity, cost, recovery difficulty, and a narrow battlefield niche are compatible explanations for that ceiling.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"},
      {id:"service",title:"Possible trial and display history",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5j writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>Trials, parades, retention near a fortress or royal arsenal, deterrent effects upon neighboring staffs, and any combat deployment are compatible possibilities.<sup class='canon-note' data-provenance='e'>[e]</sup> The author does not establish that a prototype was completed or entered service.</p><!-- altwwii-writer-block:end -->"},
      {id:"meaning",title:"What the possibility represents",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-o0m5k writer=g kind=revision created=2026-08-16T10:27:00-06:00 --><p>The numerous princely customers create a large market for unusual limited military purchases.<sup class='canon-note' data-provenance='a'>[a]</sup> One ruler, one frontier problem, sufficient bullion, and a willing workshop as the complete explanation for the Object 279 possibility is compatible interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"princely-arms-market.html",kicker:"Procurement system",label:"Princely Arms Market"},{href:"central-indian-princely-states.html",kicker:"Probable user region",label:"Central Indian Princely States"},{href:"hyderabadi-arms-industry.html",kicker:"Design and construction",label:"Hyderabadi Arms Industry"},{href:"soviet-military-industrial-diaspora.html",kicker:"Technical origin",label:"Soviet Military-Industrial Diaspora"}],
    facts:[["Status","Author-allowed possibility; completion open"],["Authorial rationale","Survival amid extremely heavy artillery fire"],["Inherited form","Soviet Object 279; curved armor and four tracks"],["Authorial ceiling","No more than perhaps one prototype"],["Possible owner","One unspecified princely state"],["Proposed design and construction","Hyderabadi émigré bureau"],["Proposed region and patron","Central India; Gwalior candidate"],["Designation, date, specifications, trials, and service","Open"]]
  })
});

const addPrincelyRelated = (slug,items) => {
  const article = window.deepArticles[slug];
  if (!article) return;
  article.related = [...items,...(article.related || []).filter(existing => !items.some(item => item.href === existing.href))];
};

